-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- Design: Centered serif masthead, monochrome rules, single-column editorial layout.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Header", "type": "header", "columnPosition": 0, "showHeading": false, "styling": {"border": {"bottom": {"display": true, "width": "86%", "height": "1px", "style": "solid", "color": "#333333"}}}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "left", "children": [{"text": "HEADER", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "JANE DOE", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JANE DOE", "fontSizeOffset": 20, "lineHeightOffset": 0, "bold": true, "color": "#252525"}], "textAlign": "center"}]}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "COMMUNICATIONS STRATEGIST", "fontSizeOffset": 1, "lineHeightOffset": 0, "color": "#252525"}], "textAlign": "center"}]}, {"label": "Contact", "value": [{"type": "paragraph", "label": "Contact", "children": [{"text": "Boston, MA | (617) 555-0138 | jane.doe@example.com", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#252525"}], "textAlign": "center"}]}]}]},
{"label": "Profile", "type": "summary", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "center", "children": [{"text": "PROFILE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "Profile", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Communications strategist with 7 years of experience shaping clear brand stories and building engaged audiences. Connects editorial planning, customer insights, and thoughtful execution to help organizations communicate with purpose.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Professional Experience", "type": "workHistory", "columnPosition": 0, "showHeading": true, "styling": {"border": {"bottom": {"display": true, "width": "86%", "height": "1px", "style": "solid", "color": "#BBBBBB"}}}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "center", "children": [{"text": "PROFESSIONAL EXPERIENCE", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "Alder House", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Senior Communications Specialist", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Alder House | Boston, MA | 2022 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Led an editorial program across email, web, and social channels, growing qualified newsletter subscribers by 32%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Developed launch messaging for 4 new services and coordinated delivery across a 9-person team.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Introduced a shared content calendar that reduced last-minute production requests by 40%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}, {"label": "Paper Finch Collective", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Content Strategist", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Paper Finch Collective | Boston, MA | 2019 - 2022", "fontSizeOffset": -0.5, "lineHeightOffset": 0}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Created customer stories and educational campaigns that increased organic inquiries by 21%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Built voice and style guidelines adopted by 3 partner teams.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}]},
{"label": "Selected Work", "type": "projects", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "center", "children": [{"text": "SELECTED WORK", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "Community Stories", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Community Stories: An Interview Series", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Planned and edited a 12-part series featuring local founders. Paired long-form interviews with concise social content, reaching 18,000 readers in its first quarter.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Core Capabilities", "type": "skills", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "center", "children": [{"text": "CORE CAPABILITIES", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "Capabilities", "fields": [{"label": "Skills", "value": [{"type": "paragraph", "label": "Skills", "children": [{"text": "Brand messaging | Editorial strategy | Copywriting | Stakeholder interviews", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Tools", "value": [{"type": "paragraph", "label": "Tools", "children": [{"text": "Campaign planning | Email marketing | Content analytics | Style guides", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Education", "type": "education", "columnPosition": 0, "showHeading": true, "styling": {}, "layout": {"display": "grid", "grid": {"columns": 1}, "padding": {"top": "0rem", "bottom": "0rem"}}, "value": [{"type": "heading", "textAlign": "center", "children": [{"text": "EDUCATION", "bold": true, "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#303030"}]}], "subsections": [{"label": "Briarwood College", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.A. English & Media Studies", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Briarwood College | 2015 - 2019", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'Jane Doe - Editorial Classic',
        '{"display": "flex", "fontFamily": "Georgia, Times New Roman, serif", "fontSize": "11.5px", "lineHeight": 1.3, "color": "#28323C", "backgroundColor": "#FFFFFF"}'::json,
        '{"padding": {"top": "2rem", "right": "2rem", "bottom": "2rem", "left": "2rem"}, "gap": {"horizontal": "0.35rem", "vertical": "0.4rem", "subsection": "0.65rem", "field": "0.13rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_columns AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT r.id, c.position, '{}'::json, c.layout,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume r
    CROSS JOIN (VALUES
        (0, '{"width": {"auto": false, "value": "100%"}, "padding": {"top": "0rem", "bottom": "0rem", "left": "1rem", "right": "1rem"}}'::json)
    ) AS c(position, layout)
    RETURNING id, position
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        (s.item->'value')::json,
        (s.item->>'showHeading')::boolean, s.position,
        (s.item->'styling')::json, (s.item->'layout')::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s
    JOIN new_columns c ON c.position = (s.item->>'columnPosition')::integer
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
